+    fn handle_visual_key(
+        &mut self,
+        key: UiKey,
+        right_content: &str,
+        right_cursor_column: Option<usize>,
+    ) -> Vec<UiAction> {
+        match key {
+            UiKey::Esc => {
+                self.mode = UiMode::Command;
+                self.visual = None;
+            }
+            UiKey::Char('v') => {
+                self.update_visual_kind(
+                    VisualKind::Character,
+                    right_content,
+                    right_cursor_column,
+                );
+            }
+            UiKey::Char('V') => {
+                self.update_visual_kind(VisualKind::Line, right_content, right_cursor_column);
+            }
+            UiKey::CtrlV => {
+                self.update_visual_kind(VisualKind::Block, right_content, right_cursor_column);
+            }
+            UiKey::Char('y') => {
+                self.copy_visual_selection(right_content, false);
+            }
+            UiKey::Char('Y') => {
+                self.copy_visual_selection(right_content, true);
+            }
+            UiKey::Char('h') | UiKey::Left => self.move_visual_cursor(0, -1),
+            UiKey::Char('j') | UiKey::Down => self.move_visual_cursor(1, 0),
+            UiKey::Char('k') | UiKey::Up => self.move_visual_cursor(-1, 0),
+            UiKey::Char('l') | UiKey::Right => self.move_visual_cursor(0, 1),
+            _ => {}
+        }
+        Vec::new()
+    }
+
+    fn update_visual_kind(
+        &mut self,
+        kind: VisualKind,
+        right_content: &str,
+        right_cursor_column: Option<usize>,
+    ) {
+        if let Some(visual) = self.visual.as_mut() {
+            visual.kind = kind;
+        } else {
+            self.start_visual_selection(kind, right_content, right_cursor_column);
+        }
+    }
+
+    fn start_visual_selection(
+        &mut self,
+        kind: VisualKind,
+        right_content: &str,
+        right_cursor_column: Option<usize>,
+    ) {
+        let Some(position) = self.current_visual_position(right_content, right_cursor_column) else {
+            return;
+        };
+        self.mode = UiMode::Visual;
+        self.visual = Some(VisualSelection {
+            pane: self.focus,
+            kind,
+            anchor: position,
+            cursor: position,
+        });
+    }
+
+    fn copy_visual_selection(&mut self, right_content: &str, force_line: bool) {
+        if self.visual.is_none() {
+            self.mode = UiMode::Command;
+            return;
+        }
+
+        let buffer = self.render_plain_tui_buffer(right_content, "", 0);
+        let text = self.selected_text_from_buffer(&buffer, force_line);
+        self.mode = UiMode::Command;
+        self.visual = None;
+
+        if text.is_empty() {
+            self.show_status_notice(
+                "nothing selected",
+                Duration::from_secs(STATUS_NOTICE_SECONDS),
+            );
+            return;
+        }
+
+        let copied_chars = text.chars().count();
+        self.clipboard_text = text;
+        self.pending_clipboard.set(true);
+        self.show_status_notice(
+            format!("copied {copied_chars} chars"),
+            Duration::from_secs(STATUS_NOTICE_SECONDS),
+        );
+    }
+
+    fn current_visual_position(
+        &self,
+        right_content: &str,
+        right_cursor_column: Option<usize>,
+    ) -> Option<VisualPosition> {
+        let pane = self.focus;
+        let rect = self.pane_inner_rect(pane)?;
+        let (row, column) = match pane {
+            PaneFocus::Left => (
+                self.control_selected
+                    .min(usize::from(rect.height.saturating_sub(1))) as u16,
+                0,
+            ),
+            PaneFocus::Right => {
+                let (row, column) =
+                    self.right_cursor_position_with_cursor(right_content, right_cursor_column);
+                (
+                    row.saturating_sub(1).saturating_sub(rect.y),
+                    column.saturating_sub(1).saturating_sub(rect.x),
+                )
+            }
+        };
+
+        Some(VisualPosition {
+            row: row.min(rect.height.saturating_sub(1)),
+            column: column.min(rect.width.saturating_sub(1)),
+        })
+    }
+
+    fn move_visual_cursor(&mut self, row_delta: isize, column_delta: isize) {
+        let Some(pane) = self.visual.as_ref().map(|visual| visual.pane) else {
+            return;
+        };
+        let Some(rect) = self.pane_inner_rect(pane) else {
+            return;
+        };
+        let Some(visual) = self.visual.as_mut() else {
+            return;
+        };
+        visual.cursor.row =
+            offset_visual_coordinate(visual.cursor.row, row_delta, rect.height.saturating_sub(1));
+        visual.cursor.column = offset_visual_coordinate(
+            visual.cursor.column,
+            column_delta,
+            rect.width.saturating_sub(1),
+        );
+    }
+
+    fn apply_visual_selection(&self, buffer: &mut Buffer) {
+        if self.mode != UiMode::Visual {
+            return;
+        }
+        let Some(visual) = self.visual.as_ref() else {
+            return;
+        };
+        let Some(rect) = self.pane_inner_rect(visual.pane) else {
+            return;
+        };
+
+        for row in 0..rect.height {
+            let Some((start_column, end_column)) =
+                self.selection_columns_for_row(visual, row, rect.width, false)
+            else {
+                continue;
+            };
+            for column in start_column..=end_column {
+                buffer
+                    .get_mut(rect.x + column, rect.y + row)
+                    .modifier
+                    .insert(Modifier::REVERSED);
+            }
+        }
+    }
+
+    fn selected_text_from_buffer(&self, buffer: &Buffer, force_line: bool) -> String {
+        let Some(visual) = self.visual.as_ref() else {
+            return String::new();
+        };
+        let Some(rect) = self.pane_inner_rect(visual.pane) else {
+            return String::new();
+        };
+
+        let mut lines = Vec::new();
+        for row in 0..rect.height {
+            let Some((start_column, end_column)) =
+                self.selection_columns_for_row(visual, row, rect.width, force_line)
+            else {
+                continue;
+            };
+            let mut line = String::new();
+            for column in start_column..=end_column {
+                line.push_str(&buffer.get(rect.x + column, rect.y + row).symbol);
+            }
+            lines.push(line.trim_end_matches(' ').to_string());
+        }
+        lines.join("\n")
+    }
+
+    fn selection_columns_for_row(
+        &self,
+        visual: &VisualSelection,
+        row: u16,
+        width: u16,
+        force_line: bool,
+    ) -> Option<(u16, u16)> {
+        if width == 0 {
+            return None;
+        }
+
+        let max_column = width - 1;
+        let row_min = visual.anchor.row.min(visual.cursor.row);
+        let row_max = visual.anchor.row.max(visual.cursor.row);
+
+        if force_line || visual.kind == VisualKind::Line {
+            return (row_min..=row_max)
+                .contains(&row)
+                .then_some((0, max_column));
+        }
+
+        if visual.kind == VisualKind::Block {
+            let column_min = visual.anchor.column.min(visual.cursor.column).min(max_column);
+            let column_max = visual.anchor.column.max(visual.cursor.column).min(max_column);
+            return (row_min..=row_max)
+                .contains(&row)
+                .then_some((column_min, column_max));
+        }
+
+        let (start, end) = ordered_visual_positions(visual);
+        if row < start.row || row > end.row {
+            return None;
+        }
+        if start.row == end.row {
+            return Some((start.column.min(max_column), end.column.min(max_column)));
+        }
+        if row == start.row {
+            return Some((start.column.min(max_column), max_column));
+        }
+        if row == end.row {
+            return Some((0, end.column.min(max_column)));
+        }
+        Some((0, max_column))
+    }
+
+    fn pane_inner_rect(&self, pane: PaneFocus) -> Option<Rect> {
+        let body_height = self.height.saturating_sub(1);
+        if body_height <= 2 {
+            return None;
+        }
+
+        let layout = self.layout();
+        match pane {
+            PaneFocus::Left if self.left_visible && layout.left_width > 2 => Some(Rect::new(
+                1,
+                1,
+                layout.left_width.saturating_sub(2),
+                body_height.saturating_sub(2),
+            )),
+            PaneFocus::Right if layout.right_width > 2 => {
+                let x = if layout.left_width > 0 {
+                    layout.left_width.saturating_add(1)
+                } else {
+                    1
+                };
+                Some(Rect::new(
+                    x,
+                    1,
+                    layout.right_width.saturating_sub(2),
+                    body_height.saturating_sub(2),
+                ))
+            }
+            _ => None,
+        }
+    }
