 fn cursor_char_count(text: &str, cursor: usize) -> usize {
     text.char_indices()
         .take_while(|(index, _)| *index < cursor)
         .count()
 }
+
+fn ordered_visual_positions(visual: &VisualSelection) -> (VisualPosition, VisualPosition) {
+    if (visual.anchor.row, visual.anchor.column) <= (visual.cursor.row, visual.cursor.column) {
+        (visual.anchor, visual.cursor)
+    } else {
+        (visual.cursor, visual.anchor)
+    }
+}
+
+fn offset_visual_coordinate(value: u16, delta: isize, max: u16) -> u16 {
+    let step = delta.unsigned_abs().min(usize::from(u16::MAX)) as u16;
+    if delta.is_negative() {
+        value.saturating_sub(step).min(max)
+    } else {
+        value.saturating_add(step).min(max)
+    }
+}
+
+fn base64_encode(bytes: &[u8]) -> String {
+    const TABLE: &[u8; 64] =
+        b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
+    let mut encoded = String::with_capacity(bytes.len().div_ceil(3) * 4);
+    for chunk in bytes.chunks(3) {
+        let first = chunk[0];
+        let second = *chunk.get(1).unwrap_or(&0);
+        let third = *chunk.get(2).unwrap_or(&0);
+
+        encoded.push(TABLE[(first >> 2) as usize] as char);
+        encoded.push(TABLE[(((first & 0b0000_0011) << 4) | (second >> 4)) as usize] as char);
+        if chunk.len() > 1 {
+            encoded.push(TABLE[(((second & 0b0000_1111) << 2) | (third >> 6)) as usize] as char);
+        } else {
+            encoded.push('=');
+        }
+        if chunk.len() > 2 {
+            encoded.push(TABLE[(third & 0b0011_1111) as usize] as char);
+        } else {
+            encoded.push('=');
+        }
+    }
+    encoded
+}

